package edu.pe.cibertec.saibm.inventario.infrastructure.persistence; import java.util.UUID; import org.springframework.stereotype.Component; import edu.pe.cibertec.saibm.inventario.application.port.out.InboxPort; @Component public class InventoryInboxAdapter implements InboxPort {private final InboxJpaRepository repo;public InventoryInboxAdapter(InboxJpaRepository r){repo=r;}public boolean firstSeen(UUID id,String type){return repo.insertIfAbsent(id,type)==1;}}
